1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_RATE = 0.1;
3	
4	const BASE_PREMIUM: Record<string, number> = {
5	  sword: 100,
6	  amulet: 60,
7	  staff: 80,
8	  potion: 40,
9	  rune: 25,
10	  moonstone: 25,
11	};
12	
13	interface Item {
14	  type: string;
15	  material?: string;
16	  enchantment?: number;
17	  cursed?: boolean;
18	}
19	
20	const HIGH_ENCHANTMENT_THRESHOLD = 5;
21	
22	const isCursed = (item: Item): boolean => item.cursed === true;
23	const isHighlyEnchanted = (item: Item): boolean =>
24	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
25	
26	const SURCHARGE_RATES: ReadonlyArray<{ applies: (item: Item) => boolean; rate: number }> = [
27	  { applies: isCursed, rate: 0.5 },
28	  { applies: isHighlyEnchanted, rate: 0.3 },
29	];
30	
31	const itemSurcharge = (item: Item): number => {
32	  const base = BASE_PREMIUM[item.type] ?? 0;
33	  const totalRate = SURCHARGE_RATES
34	    .filter(({ applies }) => applies(item))
35	    .reduce((sum, { rate }) => sum + rate, 0);
36	  return base * totalRate;
37	};
38	
39	const itemsSurcharge = (items: Item[]): number =>
40	  items.reduce((sum, item) => sum + itemSurcharge(item), 0);
41	
42	interface QuoteStep {
43	  op: "quote";
44	  items: Item[];
45	}
46	
47	interface Scenario {
48	  customer: { yearsWithMHPCO: number };
49	  steps: QuoteStep[];
50	}
51	
52	interface QuoteResult {
53	  premium: number;
54	}
55	
56	interface ScenarioResult {
57	  results: QuoteResult[];
58	}
59	
60	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
61	const COMPONENT_BLOCK_SIZE = 3;
62	const COMPONENT_BLOCK_BASE = 60;
63	
64	const roundUpInMHPCOsFavor = (amount: number): number => Math.ceil(amount);
65	
66	const groupCountsByType = (items: Item[]): Map<string, number> => {
67	  const counts = new Map<string, number>();
68	  for (const item of items) {
69	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
70	  }
71	  return counts;
72	};
73	
74	const typeBasePremium = (type: string, count: number): number => {
75	  if (COMPONENT_TYPES.has(type) && count === COMPONENT_BLOCK_SIZE) {
76	    return COMPONENT_BLOCK_BASE;
77	  }
78	  return BASE_PREMIUM[type] * count;
79	};
80	
81	const itemsBasePremium = (items: Item[]): number =>
82	  [...groupCountsByType(items)].reduce(
83	    (total, [type, count]) => total + typeBasePremium(type, count),
84	    0,
85	  );
86	
87	const firstInsuranceSurcharge = (base: number): number => base * FIRST_INSURANCE_RATE;
88	
89	const LOYALTY_YEARS_THRESHOLD = 2;
90	const LOYALTY_DISCOUNT_RATE = 0.2;
91	
92	interface Customer {
93	  yearsWithMHPCO: number;
94	}
95	
96	const isLoyalCustomer = (customer: Customer): boolean =>
97	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
98	
99	const loyaltyDiscount = (customer: Customer, base: number): number =>
100	  isLoyalCustomer(customer) ? base * LOYALTY_DISCOUNT_RATE : 0;
101	
102	const quotePremium = ({ items }: QuoteStep, customer: Customer): number => {
103	  const base = itemsBasePremium(items);
104	  return roundUpInMHPCOsFavor(
105	    base + itemsSurcharge(items) + firstInsuranceSurcharge(base) - loyaltyDiscount(customer, base) + PROCESSING_FEE,
106	  );
107	};
108	
109	export const runScenario = (scenario: Scenario): ScenarioResult => ({
110	  results: scenario.steps.map((step) => ({ premium: quotePremium(step, scenario.customer) })),
111	});
